public List<List<Integer>> pacificAtlantic(int[][] heights) {
    int m = heights.length, n = heights[0].length;
    boolean[][] pacific = new boolean[m][n];
    boolean[][] atlantic = new boolean[m][n];
    for (int r = 0; r < m; r++) {
        dfs(heights, r, 0, pacific);       // left col → Pacific
        dfs(heights, r, n - 1, atlantic);  // right col → Atlantic
    }
    for (int c = 0; c < n; c++) {
        dfs(heights, 0, c, pacific);       // top row → Pacific
        dfs(heights, m - 1, c, atlantic);  // bottom row → Atlantic
    }
    List<List<Integer>> res = new ArrayList<>();
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (pacific[r][c] && atlantic[r][c]) {
                res.add(Arrays.asList(r, c));
            }
        }
    }
    return res;
}

private void dfs(int[][] h, int r, int c, boolean[][] ocean) {
    ocean[r][c] = true;
    int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
    for (int[] d : dirs) {
        int nr = r + d[0], nc = c + d[1];
        if (nr >= 0 && nr < h.length && nc >= 0 && nc < h[0].length
                && !ocean[nr][nc] && h[nr][nc] >= h[r][c]) {
            dfs(h, nr, nc, ocean);
        }
    }
}

code.python:
def pacificAtlantic(self, heights: list[list[int]]) -> list[list[int]]:
    m, n = len(heights), len(heights[0])
    pacific, atlantic = set(), set()
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(r: int, c: int, ocean: set, prev: int) -> None:
        if (r < 0 or r >= m or c < 0 or c >= n
                or (r, c) in ocean or heights[r][c] < prev):
            return
        ocean.add((r, c))
        for dr, dc in dirs:
            dfs(r + dr, c + dc, ocean, heights[r][c])

    for r in range(m):
        dfs(r, 0, pacific, heights[r][0])        # left col
        dfs(r, n - 1, atlantic, heights[r][n - 1])  # right col
    for c in range(n):
        dfs(0, c, pacific, heights[0][c])        # top row
        dfs(m - 1, c, atlantic, heights[m - 1][c])  # bottom row

    return [[r, c] for r in range(m) for c in range(n)
            if (r, c) in pacific and (r, c) in atlantic]

